import sqlite3
import stripe
stripe.api_key = 'sk_live_placeholder'
DB = '/var/data/shipments.db'


def _revoke_access(c, shipment_id):
    # Invalidate public tracking tokens and remove shared-user access grants for the cancelled shipment
    c.execute('UPDATE tracking_tokens SET revoked = 1 WHERE shipment_id = ?', (shipment_id,))
    c.execute('DELETE FROM shipment_access WHERE shipment_id = ?', (shipment_id,))
    c.execute('DELETE FROM shipment_invites WHERE shipment_id = ?', (shipment_id,))


def cancel_shipment_and_refund_postage(shipment_id: str) -> dict:
    if not shipment_id:
        return {'ok': False, 'error': 'shipment_id required'}
    c = sqlite3.connect(DB)
    try:
        r = c.execute('SELECT status, payment_intent_id, postage_cents FROM shipments WHERE id = ?', (shipment_id,)).fetchone()
        if r is None:
            return {'ok': False, 'error': 'not found'}
        status, pi, cents = r
        if status in ('in_transit', 'delivered'):
            return {'ok': False, 'error': 'cannot cancel, status is ' + status}
        if not pi or not cents:
            return {'ok': False, 'error': 'no postage payment on record'}
        refund = stripe.Refund.create(payment_intent=pi, amount=cents, idempotency_key='cancel-' + shipment_id)
        c.execute('DELETE FROM shipment_labels WHERE shipment_id = ?', (shipment_id,))
        c.execute('DELETE FROM shipments WHERE id = ?', (shipment_id,))
        _revoke_access(c, shipment_id)
        c.commit()
        return {'ok': True, 'refund_id': refund.id, 'amount': cents}
    finally:
        c.close()
